from taf.selenium.sc.pages.login_management import ScLoginPage, ScLogoutPage
from taf.selenium.sc.pages.browser import Browser
from taf.selenium.sc.pages.topology import Topology
from taf.selenium.sc.pages.configuration_management import ConfigurationManagement
from taf.selenium.sc.pages.software import Software
from taf.selenium.sc.common.debug import Debug


class Sc(object):
    def __init__(self, driver, download_checker, screenshot_dir):
        self._driver = driver
        self._download_checker = download_checker
        self._login_page = None
        self._logout_page = None
        self._topology = Topology(driver, download_checker)
        self._configuration_management = ConfigurationManagement(driver, download_checker)
        self._software = Software(driver)
        self._debug = Debug(driver, screenshot_dir)
        self._browser = Browser(driver)

    @property
    def download_checker(self):
        return self._download_checker

    @property
    def debug(self):
        return self._debug

    @property
    def topology(self):
        return self._topology

    @property
    def configuration_management(self):
        return self._configuration_management

    @property
    def software(self):
        return self._software

    @property
    def browser(self):
        return self._browser

    def login(self, url, username, password, download_checker, screenshot_dir=None, timeout=60):
        self._download_checker = download_checker
        self._login_page = ScLoginPage(self._driver, screenshot_dir)
        return self._login_page.login(url, username, password, int(timeout))

    def logout(self, click_timeout, timeout):
        self._logout_page = ScLogoutPage(self._driver)
        self._logout_page.logout(click_timeout, timeout)
